WITH recent_accounts AS (SELECT * FROM accounts WHERE YEAR(opened_date) >= 2023 AND (account_type NOT IN ('CREDIT', 'LOAN') OR customer_id IS NOT NULL)), balance_bucket_summary AS (SELECT CASE WHEN balance >= 73000 THEN 'high' WHEN balance >= 6000 THEN 'mid' ELSE 'low' END AS balance_bucket, status, ROUND(AVG(balance), 2) AS avg_balance, COUNT(*) AS cnt FROM recent_accounts GROUP BY CASE WHEN balance >= 73000 THEN 'high' WHEN balance >= 6000 THEN 'mid' ELSE 'low' END, status) SELECT balance_bucket, status, avg_balance, cnt FROM balance_bucket_summary WHERE cnt >= 8 ORDER BY avg_balance, balance_bucket, status LIMIT 10;
